/**
 * Fixture F1 as wire `EnrichedEvent`s (PRD-006 §1.4–§1.7), built from the
 * golden raw rows in `docs/reference/samples/f1/raw/{events,event_items}.jsonl`
 * (generated by `docs/reference/samples/generate.py`; never edited here).
 *
 * The raw files are the ClickHouse row shape (`exp_ids`, `exp_var_ids`,
 * `exp_session_starts`, items in a separate table). This module turns them back
 * into what the edge sends the collector: one `exp` tuple list
 * `[experiment_id, variation_id, session_start, session_idx]`, top-level
 * `items[]`, flat string `props`, epoch-ms timestamps. `session_idx` is the
 * rank of the session start per (visitor, experiment) — v3's D3 return is 2.
 *
 * Shared on purpose: P5's platform-only harness (`scripts/e2e/prd006`) can
 * import `loadF1WireEvents` instead of re-encoding the table.
 */

import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export type ExpTuple = readonly [number, number, number, number];

export interface WireItem {
  readonly item_id: string;
  readonly product_id?: string;
  readonly item_name?: string;
  readonly item_variant?: string;
  readonly price?: number;
  readonly quantity?: number;
  readonly discount?: number;
}

/** Collector `/_ingest` event (edge-enriched). Optional fields are omitted when empty. */
export type WireEvent = Readonly<Record<string, unknown>> & {
  readonly event_id: string;
  readonly event_name: string;
  readonly client_ts: number;
  readonly server_ts: number;
  readonly project_id: number;
  readonly visitor_id: string;
};

interface RawEvent {
  readonly [key: string]: unknown;
  readonly event_id: string;
  readonly event_name: string;
  readonly client_ts: string;
  readonly server_ts: string;
  readonly visitor_id: string;
  readonly experiment_id: number | null;
  readonly variation_id: number | null;
  readonly exp_ids: readonly number[];
  readonly exp_var_ids: readonly number[];
  readonly exp_session_starts: readonly number[];
  readonly goal_id: number;
  readonly value_native: number;
  readonly currency: string;
  readonly order_id: string;
  readonly items_count: number;
  readonly purchase_type: string;
  readonly parent_order_id: string;
  readonly page_type: string;
  readonly cart_id: string;
  readonly props: Readonly<Record<string, unknown>>;
}

interface RawItem {
  readonly event_id: string;
  readonly item_id: string;
  readonly product_id: string;
  readonly item_name: string;
  readonly item_variant: string;
  readonly price: number | null;
  readonly quantity: number;
  readonly discount: number;
}

/** Envelope + enrichment fields copied verbatim when non-empty. */
const COPY_FIELDS = [
  'session_id',
  'url',
  'referrer',
  'consent_state',
  'tracker_version',
  'viewport_w',
  'viewport_h',
  'screen_w',
  'screen_h',
  'country',
  'region',
  'region_subdivision',
  'city',
  'device_type',
  'browser',
  'os',
  'os_name',
  'os_version',
  'browser_name',
  'browser_version',
  'is_bot',
  'in_experiment',
  'utm_source',
  'utm_medium',
  'utm_campaign',
  'utm_term',
  'utm_content',
  'entry_referrer',
  'entry_url',
  'entry_utm_source',
  'entry_utm_medium',
  'entry_utm_campaign',
  'entry_utm_term',
  'entry_utm_content',
  'click_id_type',
  'referrer_domain',
  'channel',
  'visit_number',
] as const;

/** Fields the ingest schema requires even when empty. */
const REQUIRED_STRINGS = ['region', 'region_subdivision', 'city', 'browser', 'os', 'url'] as const;

const toEpochMs = (chTs: string): number => Date.parse(`${chTs.replace(' ', 'T')}Z`);

function readJsonl<T>(file: string): T[] {
  return readFileSync(file, 'utf8')
    .split('\n')
    .filter((l) => l.trim().length > 0)
    .map((l) => JSON.parse(l) as T);
}

/** session_idx per (visitor, experiment, session_start): rank of the start, 1-based. */
function sessionIndex(
  events: readonly RawEvent[],
): (v: string, exp: number, start: number) => number {
  const starts = new Map<string, Set<number>>();
  for (const e of events) {
    e.exp_ids.forEach((exp, i) => {
      const key = `${e.visitor_id}|${exp}`;
      const set = starts.get(key) ?? new Set<number>();
      const start = e.exp_session_starts[i];
      if (start !== undefined) set.add(start);
      starts.set(key, set);
    });
  }
  return (v, exp, start) => {
    const sorted = [...(starts.get(`${v}|${exp}`) ?? [])].sort((a, b) => a - b);
    return sorted.indexOf(start) + 1;
  };
}

function toItem(raw: RawItem): WireItem {
  return {
    item_id: raw.item_id,
    ...(raw.product_id ? { product_id: raw.product_id } : {}),
    ...(raw.item_name ? { item_name: raw.item_name } : {}),
    ...(raw.item_variant ? { item_variant: raw.item_variant } : {}),
    ...(raw.price !== null ? { price: raw.price } : {}),
    quantity: raw.quantity,
    ...(raw.discount ? { discount: raw.discount } : {}),
  };
}

function toWire(
  raw: RawEvent,
  items: readonly RawItem[],
  idx: (v: string, exp: number, start: number) => number,
): WireEvent {
  const copied = Object.fromEntries(
    COPY_FIELDS.filter((k) => raw[k] !== '' && raw[k] !== null && raw[k] !== undefined).map((k) => [
      k,
      raw[k],
    ]),
  );
  const required = Object.fromEntries(REQUIRED_STRINGS.map((k) => [k, String(raw[k] ?? '')]));
  const exp: ExpTuple[] = raw.exp_ids.map((id, i) => {
    const variation = raw.exp_var_ids[i] ?? 0;
    const start = raw.exp_session_starts[i] ?? 0;
    return [id, variation, start, idx(raw.visitor_id, id, start)] as const;
  });
  const props = Object.fromEntries(Object.entries(raw.props).map(([k, v]) => [k, String(v)]));
  return {
    ...required,
    ...copied,
    event_id: raw.event_id,
    event_name: raw.event_name,
    client_ts: toEpochMs(raw.client_ts),
    server_ts: toEpochMs(raw.server_ts),
    project_id: Number(raw.project_id),
    visitor_id: raw.visitor_id,
    exp,
    ...(raw.experiment_id !== null ? { experiment_id: raw.experiment_id } : {}),
    ...(raw.variation_id !== null ? { variation_id: raw.variation_id } : {}),
    ...(raw.goal_id > 0 ? { goal_id: raw.goal_id } : {}),
    ...(raw.currency ? { value_native: raw.value_native, currency: raw.currency } : {}),
    ...(raw.order_id ? { order_id: raw.order_id } : {}),
    ...(raw.purchase_type ? { purchase_type: raw.purchase_type } : {}),
    ...(raw.parent_order_id ? { parent_order_id: raw.parent_order_id } : {}),
    ...(raw.items_count > 0 ? { items_count: raw.items_count } : {}),
    ...(raw.page_type ? { page_type: raw.page_type } : {}),
    ...(raw.cart_id ? { cart_id: raw.cart_id } : {}),
    ...(items.length > 0 ? { items: items.map(toItem) } : {}),
    ...(Object.keys(props).length > 0 ? { props } : {}),
  };
}

export interface F1Wire {
  readonly events: readonly WireEvent[];
  /** Raw item rows per event_id (what `event_items` must contain after ingest). */
  readonly itemRows: number;
}

export function loadF1WireEvents(platformDir: string): F1Wire {
  const dir = join(platformDir, 'docs', 'reference', 'samples', 'f1', 'raw');
  const raws = readJsonl<RawEvent>(join(dir, 'events.jsonl'));
  const items = readJsonl<RawItem>(join(dir, 'event_items.jsonl'));
  const byEvent = new Map<string, RawItem[]>();
  for (const item of items) {
    byEvent.set(item.event_id, [...(byEvent.get(item.event_id) ?? []), item]);
  }
  const idx = sessionIndex(raws);
  return {
    events: raws.map((raw) => toWire(raw, byEvent.get(raw.event_id) ?? [], idx)),
    itemRows: items.length,
  };
}
